// ═══════════════════════════════════════════════════════════════════════════
//  EvaluationTable.tsx — Common reusable table component
//  EvaluationConfig values மட்டும் import
//  Features: shimmer skeleton, sortable columns, hover tooltip, evaluate icon
// ═══════════════════════════════════════════════════════════════════════════

import React, { useState } from "react";
import styles from "./EvaluationTable.module.scss";
import {
  EvalAlertOptions,
  EvalInterviewLevels,
  EvalMessages,
  EvalNavigationPaths,
  EvalRoleID,
  EvalStatusId,
  EvalUIConfig,
} from "../../config/EvaluationConfig";
import {
  EvaluationCandidate,
  ScoreSheetResult,
  TooltipEntry,
} from "../../services/IEvaluationService";
import { TableRow, isSkeleton } from "../../hooks/useEvaluationData";
import * as moment from "moment";

// ── Sort ──────────────────────────────────────────────────────────────────
type SortKey = keyof Pick<
  EvaluationCandidate,
  "applicantName" | "positionTitle" | "interviewDate" | "interviewLevel" | "grade"
>;

// ── Props ─────────────────────────────────────────────────────────────────
interface EvaluationTableProps {
  rows: TableRow[];
  tooltipData: TooltipEntry[] | null;
  currentRoleID: string[];            // props.CurrentRoleID — navigation path decision
  navigation: (path: string, options?: any) => void;  // props.navigation
  tabValue: string;                   // props.TabValue
  onHover: (statusId: number | string, candidateID: number) => void;
  onEvaluate: (row: EvaluationCandidate) => Promise<ScoreSheetResult>;
  onShowAlert: (msg: string, type: string) => void;
  onRefresh: () => void;
}

// ─────────────────────────────────────────────────────────────────────────────

const EvaluationTable: React.FC<EvaluationTableProps> = ({
  rows,
  tooltipData,
  currentRoleID,
  navigation,
  tabValue,
  onHover,
  onEvaluate,
  onShowAlert,
  onRefresh,
}) => {
  const [sortKey, setSortKey]      = useState<SortKey>(EvalUIConfig.DefaultSortKey);
  const [sortDir, setSortDir]      = useState<"asc"|"desc">(EvalUIConfig.DefaultSortDir);
  const [hoveredId, setHoveredId]  = useState<number | null>(null);
  const [loadingId, setLoadingId]  = useState<number | null>(null);

  // ── Sort ──────────────────────────────────────────────────────────────────
  const handleSort = (key: SortKey) => {
    setSortDir((d) => sortKey === key ? (d === "asc" ? "desc" : "asc") : "asc");
    setSortKey(key);
  };

  const sortedRows = [...rows].sort((a, b) => {
    if (isSkeleton(a) || isSkeleton(b)) return 0;
    const va = String((a as EvaluationCandidate)[sortKey] ?? "");
    const vb = String((b as EvaluationCandidate)[sortKey] ?? "");
    return sortDir === "asc" ? va.localeCompare(vb) : vb.localeCompare(va);
  });

  // ── Navigation path — same logic as InterviewPanelList handleRedirectView ─
  const getNavigationPath = (statusId: number | string): string => {
    if (statusId === EvalStatusId.InterviewScheduled) {
      if (
        currentRoleID.includes(EvalRoleID.HOD) ||
        currentRoleID.includes(EvalRoleID.LineManager)
      ) return EvalNavigationPaths.HODLevel1;
      if (currentRoleID.includes(EvalRoleID.InterviewPanel))
        return EvalNavigationPaths.PanelLevel1;
      return EvalNavigationPaths.DefaultLevel1;
    }
    if (statusId === EvalStatusId.InterviewScheduledforLevel2) {
      if (
        currentRoleID.includes(EvalRoleID.HOD) ||
        currentRoleID.includes(EvalRoleID.LineManager)
      ) return EvalNavigationPaths.HODLevel2;
      if (currentRoleID.includes(EvalRoleID.InterviewPanel))
        return EvalNavigationPaths.PanelLevel2;
      return EvalNavigationPaths.DefaultLevel2;
    }
    return "";
  };

  // ── Evaluate icon click — same logic as InterviewPanelList (line 272–358) ─
  const handleEvaluateClick = async (row: EvaluationCandidate) => {
    setLoadingId(row.id);
    try {
      // Date guard — same as handleRedirectView (line 76–86)
      const interviewDateStr = moment(
        row.interviewDateTime,
        EvalUIConfig.InterviewDateDisplayFormat
      ).format(EvalUIConfig.CompareDateFormat);
      const todayDateStr = moment(new Date()).format(EvalUIConfig.CompareDateFormat);

      if (todayDateStr < interviewDateStr) {
        // Interview date is in the future — show alert
        onShowAlert(
          `Interview is scheduled for ${interviewDateStr}. You can evaluate on or after the interview date.`,
          EvalAlertOptions.Error
        );
        return;
      }

      // Score sheet check
      const result = await onEvaluate(row);
      if (!result.canProceed) {
        const msg =
          result.level === EvalInterviewLevels.Level1
            ? EvalMessages.InterviewScoredAlready
            : EvalMessages.InterviewScoreCommentsAlready;
        onShowAlert(msg, EvalAlertOptions.Error);
        return;
      }

      // Navigate
      const path = getNavigationPath(row.statusId);
      if (!path) return;

      navigation(path, {
        state: {
          ID:            row.id,
          tab:           tabValue,
          StatusId:      row.statusId,
          Status:        row.status,
          TabName:       "Evaluation",
          RecruitmentID: row.recruitmentID,
          InterviewLevel:row.interviewLevel,
          JobCodeID:     row.jobCodeID,
        },
      });
    } finally {
      setLoadingId(null);
    }
  };

  // ── Sort icon ─────────────────────────────────────────────────────────────
  const SortIcon: React.FC<{ col: SortKey }> = ({ col }) => (
    <span className={styles.sortIcon}>
      {sortKey === col ? (sortDir === "asc" ? "↑" : "↓") : "↑↓"}
    </span>
  );

  // ─────────────────────────────────────────────────────────────────────────
  return (
    <div className={styles.wrapper}>
      <table className={styles.table}>

        {/* ── Header ── */}
        <thead>
          <tr>
            <th onClick={() => handleSort("applicantName")}>
              APPLICANTNAME <SortIcon col="applicantName" />
            </th>
            <th onClick={() => handleSort("positionTitle")}>
              POSITION TITLE <SortIcon col="positionTitle" />
            </th>
            <th onClick={() => handleSort("interviewDate")}>
              INTERVIEW DATE <SortIcon col="interviewDate" />
            </th>
            <th onClick={() => handleSort("interviewLevel")}>
              INTERVIEW LEVELS <SortIcon col="interviewLevel" />
            </th>
            <th onClick={() => handleSort("grade")}>
              GRADE <SortIcon col="grade" />
            </th>
            <th>ATTACHMENTS</th>
            <th>STATUS</th>
            <th>ACTION</th>
          </tr>
        </thead>

        {/* ── Body ── */}
        <tbody>
          {sortedRows.map((row, idx) =>
            isSkeleton(row) ? (

              // ── Skeleton shimmer row ──────────────────────────────────────
              <tr key={`sk-${idx}`} className={styles.skRow}>
                {[65, 80, 55, 45, 30, 25, 60, 40].map((w, ci) => (
                  <td key={ci}>
                    <span className={styles.shimmer} style={{ width: `${w}%` }} />
                  </td>
                ))}
              </tr>

            ) : (

              // ── Real data row ─────────────────────────────────────────────
              <tr key={(row as EvaluationCandidate).id} className={styles.row}>

                {/* Applicant name */}
                <td className={styles.nameCell}>
                  {(row as EvaluationCandidate).applicantName}
                </td>

                {/* Position title */}
                <td className={styles.posCell}>
                  {(row as EvaluationCandidate).positionTitle}
                </td>

                {/* Interview date */}
                <td>{(row as EvaluationCandidate).interviewDate}</td>

                {/* Interview level */}
                <td>{(row as EvaluationCandidate).interviewLevel}</td>

                {/* Grade */}
                <td>
                  <div className={styles.grade}>
                    <span>{(row as EvaluationCandidate).grade}</span>
                    {(row as EvaluationCandidate).gradeLabel && (
                      <span className={styles.gradeLabel}>
                        {(row as EvaluationCandidate).gradeLabel}
                      </span>
                    )}
                  </div>
                </td>

                {/* Attachments */}
                <td>
                  <span className={styles.attach}>
                    📎 {(row as EvaluationCandidate).attachments}
                  </span>
                </td>

                {/* Status + hover tooltip */}
                <td>
                  <div
                    className={styles.statusWrap}
                    onMouseEnter={() => {
                      setHoveredId((row as EvaluationCandidate).id);
                      onHover(
                        (row as EvaluationCandidate).statusId,
                        (row as EvaluationCandidate).id
                      );
                    }}
                    onMouseLeave={() => setHoveredId(null)}
                  >
                    <span className={styles.dot} />
                    <span>{(row as EvaluationCandidate).status}</span>

                    {/* Tooltip — same as ToolTipButton component */}
                    {hoveredId === (row as EvaluationCandidate).id &&
                      tooltipData?.length ? (
                      <div className={styles.tooltip}>
                        {tooltipData.map((entry, i) => (
                          <div key={i} className={styles.tooltipRow}>
                            <span className={styles.tooltipName}>{entry.Key}</span>
                            <span
                              className={`${styles.badge} ${
                                entry.Value === "Completed"
                                  ? styles.completed
                                  : styles.pending
                              }`}
                            >
                              {entry.Value}
                            </span>
                          </div>
                        ))}
                      </div>
                    ) : null}
                  </div>
                </td>

                {/* Action — Viewicon same as InterviewPanelList line 371–383 */}
                <td>
                  <div className={styles.actionCell}>
                    <img
                      src={require("../../../../assets/Viewicon.svg")}
                      alt="View"
                      className={`${styles.viewIcon} ${
                        loadingId === (row as EvaluationCandidate).id
                          ? styles.loading
                          : ""
                      }`}
                      onClick={() =>
                        handleEvaluateClick(row as EvaluationCandidate)
                      }
                    />
                  </div>
                </td>
              </tr>
            )
          )}

          {/* Empty state */}
          {sortedRows.length === 0 && (
            <tr>
              <td colSpan={8} className={styles.empty}>
                No candidates found.
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
};

export default EvaluationTable;
